#include "../src/database/DatabaseSchema.h"
#include "../src/services/application/HostCollectionMutationService.h"
#include "../src/services/application/dto/RemoteCollectionMutationDtos.h"
#include <QCoreApplication>
#include <QSqlDatabase>
#include <QSqlQuery>
#include <QTemporaryDir>
#include <QUuid>
#include <cstdio>
namespace{bool need(bool x,const char*m){if(!x)std::fprintf(stderr,"%s\n",m);return x;}HostWriteExecutor::MutationOutcome run(const QSqlDatabase&db,const QString&o,const RemoteCollectionMutationDto::Request&r){RemoteMutationDto::Error e;auto m=HostCollectionMutationService::createMutation(o,RemoteCollectionMutationDto::toMetadata(o,r),&e);return m?m(db):HostWriteExecutor::MutationOutcome{};}RemoteCollectionMutationDto::ExpectedState expected(const QJsonObject&i){return{i["modifiedUtc"].toString(),i["type"].toString(),i["setNumber"].toString(),i["minifigNumber"].toString(),i["state"].toString(),i["condition"].toString(),i["completeness"].toString(),i["nickname"].toString(),i["notes"].toString(),(qint64)i["storageId"].toDouble(),(qint64)i["sourceBuildId"].toDouble(),i["active"].toBool()};}}
int main(int argc,char**argv){QCoreApplication app(argc,argv);QTemporaryDir tmp;bool ok=true;QString n="remote-collection-"+QUuid::createUuid().toString();QSqlDatabase db=QSqlDatabase::addDatabase("QSQLITE",n);db.setDatabaseName(tmp.filePath("db.sqlite"));ok&=need(db.open()&&DatabaseSchema::initialize(db),"schema failed");QSqlQuery q(db);ok&=need(q.exec("INSERT INTO workspace(name,description,created_utc,modified_utc,is_active) VALUES('W','',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,1)"),"workspace");int w=q.lastInsertId().toInt();ok&=need(q.exec("INSERT INTO set_catalog(set_number,name,year,theme_id,num_parts,image_url,created_utc,modified_utc) VALUES('1000-1','Set',2026,1,1,'',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)"),"set");ok&=need(q.exec("INSERT INTO minifig_catalog(name,num_parts,image_url,is_active,created_utc,modified_utc) VALUES('Fig',1,'',1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)"),"fig");int f=q.lastInsertId().toInt();ok&=need(q.exec(QString("INSERT INTO minifig_external_identifier(minifig_catalog_id,provider,external_id,source,is_active,created_utc,modified_utc) VALUES(%1,'Rebrickable','fig-1','test',1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)").arg(f)),"fig id");int type=0;q.exec("SELECT id FROM storage_location_type LIMIT 1");if(q.next())type=q.value(0).toInt();ok&=need(q.exec(QString("INSERT INTO storage_location(workspace_id,parent_location_id,location_type_id,name,description,sort_order,is_active,allows_inventory,allows_collection,created_utc,modified_utc) VALUES(%1,NULL,%2,'Display','',0,1,0,1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)").arg(w).arg(type)),"location");int loc=q.lastInsertId().toInt();RemoteCollectionMutationDto::Request add;add.workspaceId=w;add.mutationId=RemoteMutationDto::newMutationId();add.sourceType="SetCatalog";add.setNumber="1000-1";add.state="Sealed";add.condition="New";add.completeness="Complete";add.storageId=loc;db.transaction();auto o=run(db,"collection.add",add);ok&=need(o.success,"Set Add failed");db.commit();QJsonObject item=o.authoritative["item"].toObject();ok&=need(item["setNumber"]=="1000-1"&&item["collectionItemId"].toInt()>0,"portable result invalid");RemoteCollectionMutationDto::Request edit;edit.workspaceId=w;edit.mutationId=RemoteMutationDto::newMutationId();edit.collectionItemId=item["collectionItemId"].toInt();edit.state="Assembled";edit.condition="Used";edit.completeness="Incomplete";edit.storageId=0;edit.nickname="Edited";edit.notes="Notes";edit.expected=expected(item);db.transaction();o=run(db,"collection.edit",edit);ok&=need(o.success,"Edit failed");db.commit();item=o.authoritative["item"].toObject();ok&=need(item["nickname"]=="Edited"&&item["storageId"].toInt()==0,"Edit authoritative invalid");auto stale=edit;stale.mutationId=RemoteMutationDto::newMutationId();db.transaction();o=run(db,"collection.edit",stale);db.rollback();ok&=need(!o.success&&o.error.code=="STALE_VERSION","stale accepted");RemoteCollectionMutationDto::Request active;active.workspaceId=w;active.mutationId=RemoteMutationDto::newMutationId();active.collectionItemId=item["collectionItemId"].toInt();active.desiredActive=false;active.expected=expected(item);db.transaction();o=run(db,"collection.setActive",active);ok&=need(o.success,"archive failed");db.rollback();ok&=need(q.exec(QString("SELECT is_active FROM collection_item WHERE id=%1").arg(active.collectionItemId))&&q.next()&&q.value(0).toInt()==1,"rollback failed");auto unknown=add;unknown.mutationId=RemoteMutationDto::newMutationId();unknown.setNumber="missing";db.transaction();o=run(db,"collection.add",unknown);db.rollback();ok&=need(!o.success&&o.error.code=="NOT_FOUND","unknown identity accepted");db.close();db={};QSqlDatabase::removeDatabase(n);return ok?0:1;}
